// Ported from the Node app's Sequelize model StudentFile (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StudentFileConfiguration : IEntityTypeConfiguration<StudentFile>
{
    public void Configure(EntityTypeBuilder<StudentFile> builder)
    {
        builder.ToTable("student_files", t =>
        {
            t.HasCheckConstraint("CK_student_files_kind", "[kind] IN (N'photo', N'document')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.Kind).HasColumnName("kind").HasColumnType("nvarchar(20)").IsRequired();
        builder.Property(e => e.Title).HasColumnName("title").HasColumnType("nvarchar(160)").HasMaxLength(160).IsRequired();
        builder.Property(e => e.OriginalName).HasColumnName("original_name").HasColumnType("nvarchar(255)").HasMaxLength(255).IsRequired();
        builder.Property(e => e.MimeType).HasColumnName("mime_type").HasColumnType("nvarchar(100)").HasMaxLength(100).IsRequired();
        builder.Property(e => e.Size).HasColumnName("size");
        builder.Property(e => e.StoredName).HasColumnName("stored_name").HasColumnType("nvarchar(64)").HasMaxLength(64).IsRequired();
        builder.Property(e => e.Data).HasColumnName("data").HasColumnType("nvarchar(max)");
        builder.Property(e => e.UploadedByName).HasColumnName("uploaded_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.CreatedAt).HasColumnName("created_at").HasColumnType("datetime2");
        builder.HasIndex(e => e.StoredName).IsUnique();
        builder.HasOne(e => e.Student).WithMany(p => p.StudentFiles).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
